refentry.refsect1:
&reftitle.description;
intdio_seek resourcefd intpos intwhenceSEEK_SET
La funzione dio_seek viene usata per modificare la posizione nel file del descrittore di file indicato.

  &reftitle.examples;



    Posizionamento in un file


<?php

$fd = dio_open('/dev/ttyS0', O_RDWR);

dio_seek($fd, 10, SEEK_SET);
// la posizione è ora a 10 caratteri dall'inizio del file

dio_seek($fd, -2, SEEK_CUR);
// la posizione è ora a 8 caratteri dall'inizio del file

dio_seek($fd, -5, SEEK_END);
// la posizione è ora a 5 caratteri dalla fine del file

dio_seek($fd, 10, SEEK_END);
// la posizione è ora a 10 caratteri oltre la fine del file.
// I 10 caratteri tra la fine del file e la posizione
// corrente vengono riempiti con zeri.

dio_close($fd);
?>
